package com.heluo.museum.auth;
import com.heluo.museum.common.api.ApiResponse;import jakarta.validation.Valid;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") public class UserController {private final JdbcTemplate jdbc;UserController(JdbcTemplate jdbc){this.jdbc=jdbc;}@PatchMapping("/me") public ApiResponse<java.util.Map<String,Object>> update(Authentication a,@Valid @RequestBody AuthController.Profile body){long id=(Long)a.getPrincipal();jdbc.update("update users set nickname=?,email=?,phone=? where id=?",body.nickname(),blank(body.email()),blank(body.phone()),id);return ApiResponse.ok(java.util.Map.of("id",id,"nickname",body.nickname(),"email",blank(body.email())==null?"":blank(body.email()),"phone",blank(body.phone())==null?"":blank(body.phone())),"profile");}private String blank(String v){return v==null||v.isBlank()?null:v.trim();}}
